import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadKcData(){const e=readFileSync(resolve(__dirname,"../../frontend/kirti-chakra-explorer/kc-data.js"),"utf-8");return new Function(e+"\nreturn { KC_INFO, KC_HISTORY, KC_ELIGIBILITY, KC_MEDAL_DESIGN, KC_HEROIC_ACTS, KC_RECIPIENTS, KC_TIMELINE, KC_FAQS };")()}describe("Kirti Chakra Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadKcData()}),describe("KC_INFO metadata",()=>{it("contains correct award metadata and statistics",()=>{expect(e.KC_INFO.id).toBe("kirti-chakra"),expect(e.KC_INFO.totalRecipients).toBe(480),expect(e.KC_INFO.ribbonColor).toContain("two orange"),expect(Array.isArray(e.KC_INFO.quickStats)).toBe(!0),expect(e.KC_INFO.quickStats.length).toBe(6)})}),describe("KC_HISTORY & MEDAL_DESIGN",()=>{it("contains history, peacetime significance, and silver medal design specs",()=>{expect(e.KC_HISTORY.overview).toBeDefined(),expect(e.KC_HISTORY.peacetimeSignificance).toBeDefined(),expect(e.KC_MEDAL_DESIGN.obverse).toContain("Ashoka Chakra"),expect(e.KC_MEDAL_DESIGN.ribbon).toContain("two orange")})}),describe("KC_RECIPIENTS catalog",()=>{it("contains heroes like Major Anuj Sood, Captain Anshuman Singh, and Sapper Prakash Jadhav",()=>{expect(Array.isArray(e.KC_RECIPIENTS)).toBe(!0),expect(e.KC_RECIPIENTS.length).toBeGreaterThanOrEqual(5);const t=e.KC_RECIPIENTS.find(e=>"anuj-sood"===e.id),a=e.KC_RECIPIENTS.find(e=>"anshuman-singh"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined(),expect(t.famousWords).toContain("Duty before self"),expect(a.citation).toContain("Siachen Glacier")})}),describe("KC_TIMELINE & FAQS",()=>{it("has timeline milestones and interactive FAQs array",()=>{expect(Array.isArray(e.KC_TIMELINE)).toBe(!0),expect(e.KC_TIMELINE.length).toBeGreaterThanOrEqual(5),expect(Array.isArray(e.KC_FAQS)).toBe(!0),expect(e.KC_FAQS.length).toBe(6)})}),describe("Landing Page Integration",()=>{it("is integrated into awards-of-india-explorer landing page",()=>{const e=readFileSync(resolve(__dirname,"../../frontend/awards-of-india-explorer/index.html"),"utf-8");expect(e).toContain("../kirti-chakra-explorer/index.html"),expect(e).toContain("Kirti Chakra")})})});